<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-6xl space-y-6">
    <PageHeader :title="t('admin_billing.payment_detail_title')" :description="t('admin_billing.payment_detail_desc')" back-to="/admin/billing/payments"><div v-if="payment?.status === 'pending'" class="flex gap-2"><button class="rounded-xl bg-rose-600 px-4 py-2.5 text-sm font-bold text-white" :disabled="busy" @click="openAction('cancel')">{{ t('admin_billing.cancel_payment') }}</button><button class="rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-bold text-slate-950" :disabled="busy" @click="openAction('expire')">{{ t('admin_billing.expire_payment') }}</button></div></PageHeader>
    <PageState :loading="loading" :error="error" :empty="!payment" :empty-text="t('admin_billing.payment_not_found')" @retry="load"><template v-if="payment">
      <div class="grid gap-4 lg:grid-cols-3"><section class="detail-card lg:col-span-2"><h2 class="section-title">{{ t('admin_billing.payment_info') }}</h2><dl class="detail-grid"><div><dt>{{ t('admin_billing.header_order_code') }}</dt><dd class="font-mono">{{ payment.order_code }}</dd></div><div><dt>{{ t('admin_billing.header_status') }}</dt><dd><StatusBadge :status="payment.status" /></dd></div><div><dt>{{ t('admin_billing.payment_type') }}</dt><dd>{{ payment.payment_type }}</dd></div><div><dt>{{ t('admin_billing.amount_snapshot') }}</dt><dd>{{ formatBillingMoney(payment.amount_snapshot ?? payment.amount, payment.currency_snapshot || 'VND') }}</dd></div><div><dt>{{ t('admin_billing.header_cycle') }}</dt><dd>{{ payment.billing_cycle_snapshot || '—' }}</dd></div><div><dt>{{ t('admin_billing.transaction_hash') }}</dt><dd class="break-all font-mono text-xs">{{ payment.transaction_hash || '—' }}</dd></div></dl></section>
      <section class="detail-card"><h2 class="section-title">{{ t('admin_billing.user_organization') }}</h2><dl class="space-y-4"><div><dt>{{ t('admin_billing.user') }}</dt><dd>{{ payment.user?.name || '—' }}</dd><dd class="text-xs text-slate-500">{{ payment.user?.email || '—' }}</dd></div><div><dt>{{ t('admin_billing.organizations') }}</dt><dd>{{ payment.organization?.name || '—' }}</dd></div><div><dt>{{ t('admin_billing.owner') }}</dt><dd>{{ payment.organization?.owner?.name || '—' }}</dd><dd class="text-xs text-slate-500">{{ payment.organization?.owner?.email || '—' }}</dd></div></dl></section></div>
      <div class="grid gap-4 lg:grid-cols-2"><section class="detail-card"><h2 class="section-title">{{ t('admin_billing.plan_package_snapshot') }}</h2><pre>{{ formatBillingJson({ plan: payment.plan_snapshot, topup: payment.topup_snapshot, duration: payment.duration_snapshot }) }}</pre></section><section class="detail-card"><h2 class="section-title">{{ t('admin_billing.token_benefits_snapshot') }}</h2><pre>{{ formatBillingJson({ token_amount: payment.token_amount_snapshot, benefits: payment.benefits_snapshot }) }}</pre></section></div>
      <section class="detail-card"><h2 class="section-title">{{ t('admin_billing.timeline') }}</h2><dl class="detail-grid sm:grid-cols-4"><div><dt>{{ t('admin_billing.created_at') }}</dt><dd>{{ formatBillingDate(payment.created_at, true) }}</dd></div><div><dt>{{ t('admin_billing.expiry') }}</dt><dd>{{ formatBillingDate(payment.expires_at, true) }}</dd></div><div><dt>{{ t('admin_billing.paid_at') }}</dt><dd>{{ formatBillingDate(payment.paid_at, true) }}</dd></div><div><dt>{{ t('admin_billing.updated_at') }}</dt><dd>{{ formatBillingDate(payment.updated_at, true) }}</dd></div></dl></section>
    </template></PageState>
    <ReasonModal v-model="actionOpen" :title="action === 'cancel' ? t('admin_billing.cancel_payment') : t('admin_billing.expire_payment')" :description="payment?.order_code || ''" :warning="t('admin_billing.payment_audit_warning')" :action-label="action === 'cancel' ? t('admin_billing.action_confirm_cancel') : t('admin_billing.action_confirm_expire')" :danger="action === 'cancel'" :busy="busy" :server-error="actionError" @submit="performAction" />
  </div></div>
</template>

<script setup lang="ts">
import type { AdminPayment } from '~/types/admin-billing'; import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import StatusBadge from '~/components/admin/billing/StatusBadge.vue'; import ReasonModal from '~/components/admin/billing/ReasonModal.vue'; import { formatBillingDate, formatBillingJson, formatBillingMoney } from '~/utils/adminBilling'
const { t } = useI18n()
definePageMeta({ layout: 'layout-admin' }); const route = useRoute(); const api = useAdminBilling(); const toast = useToast(); const payment = ref<AdminPayment | null>(null); const loading = ref(true); const error = ref(''); const busy = ref(false); const actionOpen = ref(false); const action = ref<'cancel'|'expire'>('cancel'); const actionError = ref('')
const load = async () => { loading.value = true; error.value = ''; try { payment.value = (await api.getPayment(String(route.params.id))).data } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }
const openAction = (value: 'cancel'|'expire') => { action.value = value; actionError.value = ''; actionOpen.value = true }
const performAction = async (reason: string) => { if (!payment.value || busy.value) return; busy.value = true; try { const response = action.value === 'cancel' ? await api.cancelPayment(payment.value.id, reason) : await api.expirePayment(payment.value.id, reason); payment.value = response.data; toast.success(t('admin_billing.payment_updated')); actionOpen.value = false } catch (e) { actionError.value = getAdminBillingErrorMessage(e); toast.error(actionError.value); if (e instanceof AdminBillingError && e.code === 'PAYMENT_ALREADY_PROCESSED') await load() } finally { busy.value = false } }
onMounted(load)
</script>
<style scoped>.detail-card{ @apply rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-white/10 dark:bg-white/5; }.section-title{ @apply mb-5 text-base font-extrabold text-slate-900 dark:text-white; }.detail-grid{ @apply grid gap-5 sm:grid-cols-2; }dt{ @apply text-xs font-bold uppercase tracking-wide text-slate-500; }dd{ @apply mt-1 font-semibold text-slate-900 dark:text-slate-100; }pre{ @apply max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-xl bg-slate-950 p-4 text-xs leading-5 text-slate-100; }</style>
